// 1. Fetch Metadata from Gemini Node 1
const metadataItem = $('Gemini - Metadata Extractor').first()?.json || {};
let metadataText = metadataItem.content?.parts?.[0]?.text || '';

// Clean JSON code blocks if present
metadataText = metadataText.replace(/```json|```/g, '').trim();

let parsedData = {};
try {
  parsedData = JSON.parse(metadataText);
} catch (e) {
  parsedData = {};
}

// 2. Fetch Formatted Markdown from Gemini Node 2
const markdownItem = $('Gemini - Markdown Formatter').first()?.json || {};
let formattedAdBody = markdownItem.content?.parts?.[0]?.text || 'No advertisement text captured.';

// Strip standard markdown code fences (```markdown ... ``` or ```json ... ```)
formattedAdBody = formattedAdBody.replace(/```markdown|```json|```/g, '').trim();

// 3. Extract purely the Markdown content starting from the first '#' heading symbol
// Discards leading braces {, JSON keys like "content": ", and opening quotes
const headerMatch = formattedAdBody.match(/#[\s\S]*/);
if (headerMatch) {
  formattedAdBody = headerMatch[0];
}

// Clean trailing JSON quotes or closing braces at the end of the text
formattedAdBody = formattedAdBody.replace(/["\}\s]+$/, '').trim();

// Unescape literal backslash newlines (\n\n) into real line breaks
formattedAdBody = formattedAdBody.replace(/\\n/g, '\n');

// 4. Extract metadata properties
const jobTitle = parsedData.job_title || parsedData.title || '';
const companyName = parsedData.company_or_university || parsedData.company || parsedData.university || '';
const jobType = parsedData.type === 'PhD' ? 'PhD' : 'Industry';
const icon = jobType === 'PhD' ? '🎓' : '💼';

// Format Title: 💼/🎓 Position Title - Company / University
let fullTitle = '';
if (jobTitle && companyName) {
  fullTitle = icon + ' ' + jobTitle + ' - ' + companyName;
} else if (jobTitle) {
  fullTitle = icon + ' ' + jobTitle;
} else {
  fullTitle = icon + ' New Job Application';
}

// Format Deadline (Stripped to YYYY-MM-DD for Notion All-Day Event)
let rawDeadline = parsedData.deadline;

let cleanDeadline = (rawDeadline && rawDeadline !== 'null' && rawDeadline !== 'N/A')
  ? String(rawDeadline).split('T')[0].split(' ')[0].trim()
  : '';

// Validate strict YYYY-MM-DD format
const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
const validDeadline = dateRegex.test(cleanDeadline) ? cleanDeadline : undefined;

const deadlineText = validDeadline ? validDeadline : 'Not Mentioned';

// Build Application Requirements Checklist
const phdChecklist = "- [ ] Targeted Academic CV\n- [ ] Cover Letter / Motivation Letter\n- [ ] Master's Degree Certificate & Transcript of Records\n- [ ] Master's Thesis / Research Proposal Abstract\n- [ ] Reference Letters / Recommendations";
const industryChecklist = "- [ ] Targeted Industry CV / Resume\n- [ ] Tailored Cover Letter (Anschreiben)\n- [ ] Master's Degree Certificate & Transcript of Records\n- [ ] Work Certificates (Arbeitszeugnisse) & Reference Letters\n- [ ] Submitted via Company Career Portal / LinkedIn / Email";

const checklistMarkdown = jobType === 'PhD' ? phdChecklist : industryChecklist;

// 5. Assemble Complete Page Body
const fullPageContent = [
  "> **Application Deadline:** " + deadlineText,
  "",
  "## 📄 Original Job Advertisement & Requirements",
  "",
  formattedAdBody,
  "",
  "---",
  "",
  "## 🎯 Application Requirements Checklist",
  checklistMarkdown,
  "",
  "---",
  "",
  "## 📞 Interview Preparation & Progress",
  "",
  "- **HR / Professor Screening Call Date:**",
  "- **Technical / Research Interview Date:**",
  "- **Key Notes & Questions to Ask:**"
].join("\n");

return [
  {
    json: {
      title: fullTitle,
      company_or_university: companyName || 'N/A',
      type: jobType,
      deadline: validDeadline,
      contact_person: parsedData.contact_person || 'N/A',
      contact_email: parsedData.contact_email || 'N/A',
      page_content: fullPageContent,
      url: $('Webhook').item?.json?.body?.url || ''
    }
  }
];
